import{_ as t,o as a,c as o,a0 as n}from"./chunks/framework.lnbZLl6b.js";const p="/projects/aquilifer/screenshots/appearance-tab.png",w=JSON.parse('{"title":"Appearance","description":"","frontmatter":{},"headers":[],"relativePath":"docs/appearance.md","filePath":"docs/appearance.md"}'),r={name:"docs/appearance.md"};function s(i,e,h,l,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h1><p>Two display preferences, from the <strong>Appearance</strong> tab in settings, both controlled with sliders: how large the extension&#39;s text reads, and how wide the toolbar popup opens.</p><p><img src="'+p+'" alt="The Appearance tab, showing the font size slider, a live preview of the popup with a fake Anthropic and OpenAI-compatible provider, and the popup width slider"></p><h2 id="font-size" tabindex="-1">Font size <a class="header-anchor" href="#font-size" aria-label="Permalink to &quot;Font size&quot;">​</a></h2><p>A single percentage that scales every piece of text together, proportionally, across the popup, settings, and every approval/unlock popup: 100% is the extension&#39;s own default size, and the range runs from 50% to 200%. It applies immediately to whichever page you&#39;re on as you move the slider, not just after you save.</p><h2 id="popup-width" tabindex="-1">Popup width <a class="header-anchor" href="#popup-width" aria-label="Permalink to &quot;Popup width&quot;">​</a></h2><p>Only affects <a href="/projects/aquilifer/docs/popup">the toolbar popup</a>&#39;s own width, in pixels. The connection-approval, rate-limit, and vault-unlock popups are separate, transient windows sized on their own, so this doesn&#39;t change them. The popup&#39;s height isn&#39;t a setting at all: like any ordinary page, it&#39;s just however tall its content happens to be.</p><p>A preview box above the slider shows a mock-up of the popup at whatever width you&#39;ve currently dragged it to, with a fake Anthropic provider and a fake OpenAI-compatible one, the same &quot;not connected to a provider&quot; text an unconnected site sees, and the Default/Set Default/Change controls each provider row has, so you can see what a populated provider list looks like, not just an empty shell. It&#39;s built from placeholder text, not the real popup content or its actual behavior (the buttons don&#39;t do anything here), since this page can&#39;t open a real one to show at true size; its own height is content-driven too, the same as the real popup&#39;s.</p><p>If you&#39;ve turned the font size up a lot, you may want to widen the popup too, the same way Aquilifer&#39;s own default width was widened when its own text got bigger: a larger font needs more room for the same content to avoid wrapping.</p>',9)])])}const f=t(r,[["render",s]]);export{w as __pageData,f as default};
